    strengths: ["Reproducibility across labs", "Regulatory-approved closed assays"],
    limitations: ["Vendor lock-in to reagent ecosystems", "Assays not interchangeable across platforms", "Capital cost for small labs"],
    technologies: ["histopathology-ihc", "companion-diagnostic", "whole-slide-scanners", "reference-laboratories"], companies: ["roche-genentech", "leica-biosystems", "agilent", "sakura-finetek"],
